#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <iomanip>
#include <cctype>
using namespace std;

using i128 = __int128_t;
using i64 = long long;
using f80 = long double;
using u64 = unsigned long long;

const int dr[4] = {1, -1, 0, 0};
const int dc[4] = {0, 0, 1, -1};

int N, T, r0, c0;
string gridL[20], gridS[20];
int dp[12][12][12][12][62];
int cap[250][250], par[250];
int dist[20][20], vis[20][20];

bool ok(int r, int c) {
    return r >= 0 && r < N && c >= 0 && c < N && gridL[r][c] != 'Y' && gridL[r][c] != 'Z';
}

void initBFS() {
    memset(dist, 0x3f, sizeof(dist));
    memset(vis, 0, sizeof(vis));
    dist[r0][c0] = 0;
    vis[r0][c0] = 1;
    queue<int> qr, qc;
    qr.push(r0); qc.push(c0);
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c = qc.front(); qc.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (ok(nr, nc) && !vis[nr][nc]) {
                dist[nr][nc] = dist[r][c] + 1;
                vis[nr][nc] = 1;
                qr.push(nr); qc.push(nc);
            }
        }
    }
}

bool pathExists(int r1, int c1, int r2, int c2, int t) {
    if (t > T) return false;
    int& ans = dp[r1][c1][r2][c2][t];
    if (ans != -1) return ans;
    if (r1 == r2 && c1 == c2) return ans = (dist[r1][c1] >= t);
    if (dist[r1][c1] <= t) return ans = false;
    for (int k = 0; k < 4; ++k) {
        int nr = r1 + dr[k];
        int nc = c1 + dc[k];
        if (ok(nr, nc) && pathExists(nr, nc, r2, c2, t + 1)) return ans = true;
    }
    return ans = false;
}

bool bfs(int s, int t) {
    memset(par, -1, sizeof(par));
    par[s] = -2;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v = s; v <= t; ++v) {
            if (par[v] == -1 && cap[u][v] > 0) {
                par[v] = u;
                q.push(v);
            }
        }
    }
    return par[t] != -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(32);

    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> gridS[i];
    for (int i = 0; i < N; ++i) cin >> gridL[i];

    vector<pair<int, int>> pts;
    vector<int> labC, sciC;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridS[i][j] == 'Z') {
                r0 = i; c0 = j;
            } else if (isdigit(gridS[i][j])) {
                pts.emplace_back(i, j);
                labC.push_back(gridL[i][j] - '0');
                sciC.push_back(gridS[i][j] - '0');
            }
        }
    }

    int m = pts.size();
    memset(cap, 0, sizeof(cap));
    for (int i = 0; i < m; ++i) {
        cap[0][i + 1] = sciC[i];
        cap[m + 1 + i][2 * m + 1] = labC[i];
    }

    initBFS();
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < m; ++j) {
            if (pathExists(pts[i].first, pts[i].second, pts[j].first, pts[j].second, 0)) {
                cap[i + 1][m + 1 + j] = 1000;
            }
        }
    }

    int flow = 0;
    while (bfs(0, 2 * m + 1)) {
        int sink = 2 * m + 1;
        int f = 1000000;
        while (par[sink] >= 0) {
            f = min(f, cap[par[sink]][sink]);
            sink = par[sink];
        }
        sink = 2 * m + 1;
        while (par[sink] >= 0) {
            cap[par[sink]][sink] -= f;
            cap[sink][par[sink]] += f;
            sink = par[sink];
        }
        flow += f;
    }

    cout << flow;
    return 0;
}
